// Function to get video metadata from URL
export function getVideoMetadata(videoUrl: string) {
  // Extract filename from URL (e.g., "http://127.0.0.1:5000/api/videos/filename.mp4" -> "filename.mp4")
  const filename = videoUrl.split('/').pop() || '';
  
  // Get frame data
  const frameMetadata = frameData[filename];
  const frameNumbers = frameMetadata ? [frameMetadata.es, frameMetadata.ed] : [];
  
  // Get cardiac data
  const cardiac = cardiacData[filename];
  const ef = cardiac ? cardiac.ef : 0.00;
  const esv = cardiac ? cardiac.esv : 0.00;
  const edv = cardiac ? cardiac.edv : 0.00;
  
  return {
    frameNumbers,
    ef,
    esv,
    edv
  };
}
